def esc(s): return html.escape(str(s), quote=True)
def page_url(path): return f'{SITE_URL}/{path.lstrip("/")}' if SITE_URL else ''
def href(path): return '/'+path.lstrip('/')
def asset(s): return href(s)

def nav(active=''):
 items=[('꿈해몽','/dreams/','dreams'),('오늘의 운세','/fortune/today/','today'),('주간운세','/fortune/weekly/','weekly'),('생활꿀팁','/life/','life')]
 links=''.join(f'<a href="{url}" class="{"active" if active==key else ""}">{name}</a>' for name,url,key in items)
 return f'<header class="site-header"><div class="container header-inner"><a class="brand" href="/" aria-label="꿀팁도사 홈"><img class="brand-avatar" src="/assets/mascot-avatar.webp" width="48" height="48" alt="" decoding="async"><span>꿀팁도사<small>오늘도 하나씩, 알아두면 쓸모 있는 꿀팁</small></span></a><nav class="primary-nav" aria-label="주 메뉴">{links}</nav><a class="search-toggle" href="/search/" aria-label="검색"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/></svg><span>검색</span></a></div></header>'

def footer():
 return f'''<footer class="site-footer"><div class="container footer-grid"><div><a class="footer-brand" href="/"><img src="/assets/mascot-avatar.webp" width="42" height="42" alt="" loading="lazy"> 꿀팁도사</a><p>꿈해몽은 가볍게, 생활정보는 꼼꼼하게.<br>하루의 궁금증을 함께 살펴보는 정보 매거진입니다.</p></div><div><strong>둘러보기</strong><a href="/dreams/">꿈해몽</a><a href="/fortune/today/">오늘의 운세</a><a href="/fortune/weekly/">주간운세</a><a href="/life/">생활꿀팁</a></div><div><strong>안내</strong><a href="/about/">사이트 소개</a><a href="/privacy/">개인정보처리방침</a><a href="/contact/">문의하기</a></div></div><div class="container footer-bottom">© {TODAY.year} 꿀팁도사 · 운세와 꿈풀이는 오락·문화 콘텐츠이며 중요한 결정을 대신하지 않습니다.</div></footer>'''

def shell(title, desc, main, active='', path='', kind='website', data=None):
 tag_title = f'{title} | 꿀팁도사' if title != '꿀팁도사' else '꿀팁도사 | 꿈해몽·오늘의 운세·생활정보'
 canon = page_url(path)
 canonical=f'<link rel="canonical" href="{esc(canon)}">' if canon else ''
 ogurl=f'<meta property="og:url" content="{esc(canon)}">' if canon else ''
 ld={'@context':'https://schema.org','@type':'WebSite' if kind=='website' else 'Article','name':tag_title,'description':desc,'inLanguage':'ko-KR'}
 if kind=='article': ld['headline']=title; ld['author']={'@type':'Organization','name':'꿀팁도사 콘텐츠팀'}; ld['datePublished']=CONTENT_CREATED_DATE; ld['dateModified']=CONTENT_CREATED_DATE
 if canon: ld['url']=canon
 if data: ld.update(data)
 schema=json.dumps(ld,ensure_ascii=False).replace('<','\\u003c')
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#fff8e9"><title>{esc(tag_title)}</title><meta name="description" content="{esc(desc)}">{canonical}<meta property="og:type" content="{'article' if kind=='article' else 'website'}"><meta property="og:site_name" content="꿀팁도사"><meta property="og:title" content="{esc(tag_title)}"><meta property="og:description" content="{esc(desc)}">{ogurl}<link rel="icon" type="image/png" href="/assets/favicon.png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><meta property="og:image" content="{SITE_URL + '/assets/mascot-logo.webp' if SITE_URL else '/assets/mascot-logo.webp'}"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{schema}</script></head><body>{nav(active)}<main id="main">{main}</main>{footer()}<script src="/assets/app.js" defer></script></body></html>'''

def write(path,content):
 p=OUT/path
 p.parent.mkdir(parents=True, exist_ok=True)
 p.write_text(content,encoding='utf-8')

def adslot(): return '<div class="ad-slot" aria-label="광고 자리"><span>ADVERTISEMENT</span><p>광고 영역 · 승인 후 활성화</p></div>'

def breadcrumb(*parts):
 chain=['<a href="/">홈</a>']
 for label,url in parts:
  chain.append(f'<a href="{url}">{esc(label)}</a>' if url else f'<span aria-current="page">{esc(label)}</span>')
 return '<div class="breadcrumbs">'+'<span class="crumb-sep">›</span>'.join(chain)+'</div>'

def article_card(item, kind='dreams'):
 url=f'/{kind}/{item["slug"]}/'
 return f'<a class="article-card" href="{url}"><div class="article-visual {"visual-dream" if kind=="dreams" else "visual-life"}"><span>{item["emoji"]}</span><span class="visual-star">✦</span></div><div class="article-content"><span class="eyebrow">{esc(item["category"])}</span><h3>{esc(item["title"])}</h3><p>{esc(item["excerpt"])}</p><span class="read-link">자세히 보기 <span aria-hidden="true">↗</span></span></div></a>'

def brand_strip():
 if CHANGECLEAN_URL.startswith('https://'):
  cta=f'<a class="btn btn-dark" href="{esc(CHANGECLEAN_URL)}" rel="sponsored noopener" target="_blank">체인지클린 알아보기 ↗</a>'
 else:
  cta='<span class="strip-pending">서비스 안내 연결은 사이트 공개 시 설정</span>'
 return f'<section class="brand-strip"><div class="strip-icon">🏡</div><div><span class="eyebrow">관련 서비스 안내</span><h3>이사·입주청소가 필요하다면?</h3><p>집 관리 정보를 읽고 전문 청소가 필요한 순간, 체인지클린을 만나보세요.</p></div>{cta}</section>'

