def listing(title,desc,items,kind,active,filters):
 cards=''.join(article_card(x,kind) for x in items)
 badges=''.join(f'<button type="button" class="filter-chip" data-filter="{esc(x)}">{esc(x)}</button>' for x in filters)
 body=f'''<div class="container listing-page">{breadcrumb((title,None))}<div class="page-heading"><span class="eyebrow">{ 'DREAM DICTIONARY' if kind=='dreams' else 'LIVING LIBRARY'}</span><h1>{esc(title)}<span class="title-spark">✦</span></h1><p>{esc(desc)}</p></div><div class="list-tools"><label class="filter-search"><span>⌕</span><input id="article-search" type="search" placeholder="궁금한 키워드를 검색해보세요" autocomplete="off" aria-label="글 검색"></label><div class="chips"><button type="button" class="filter-chip active" data-filter="전체">전체</button>{badges}</div></div><p class="list-count" aria-live="polite">총 {len(items)}개의 글</p><div class="article-grid" id="filtered-articles">{cards}</div><div id="empty-state" class="empty-state" hidden>해당하는 글이 없어요. 다른 검색어를 입력해보세요.</div>{brand_strip() if kind=='life' else ''}</div>'''
 return shell(title,desc,body,active,kind+'/', data={'@type':'CollectionPage'})

def article(item,kind):
 isdream=kind=='dreams'
 title=item['title']; label='꿈해몽' if isdream else '생활꿀팁'
 paragraph='<p>'+esc(item['intro'])+'</p>'
 for h,p in item['sections']:
  paragraph+=f'<h2>{esc(h)}</h2><p>{esc(p)}</p>'
 if isdream:
  paragraph+=f'<div class="note-box"><b>✷ 꿀팁도사의 한마디</b><p>{esc(item["tip"])}</p></div><p class="disclaimer">꿈해몽은 전통적 상징을 재미로 살펴보는 문화 콘텐츠입니다. 꿈이 미래의 사실이나 금전적 결과를 예측한다고 볼 근거는 없습니다.</p>'
 else:
  if item.get('sources'):
   paragraph+='<div class="source-list"><b>관련 공식 사이트</b><ul>'+''.join(f'<li><a href="{esc(url)}" target="_blank" rel="noopener noreferrer">{esc(t)} ↗</a></li>' for t,url in item['sources'])+'</ul></div>'
  paragraph+='<p class="disclaimer">생활정보는 일반적인 안내입니다. 실제 신청·계약·법적 판단은 상황에 따라 달라질 수 있으므로 관계 기관의 최신 안내를 확인하세요.</p>'
 related = [x for x in (DREAMS if isdream else LIFE) if x['slug'] != item['slug']][:3]
 side=''.join(f'<a href="/{kind}/{x["slug"]}/">{x["emoji"]} {esc(x["title"])}</a>' for x in related)
 body=f'''<div class="container article-page">{breadcrumb((label,f'/{kind}/'),(title,None))}<div class="article-layout"><article class="article-main"><header class="article-header"><span class="eyebrow">{esc(item['category'])}</span><h1>{esc(title)}</h1><p class="article-lead">{esc(item['excerpt'])}</p><div class="article-meta">꿀팁도사 콘텐츠팀 <span>·</span> {CONTENT_CREATED_DATE} 작성</div></header><div class="article-hero-visual {'visual-dream' if isdream else 'visual-life'}"><span>{item['emoji']}</span><span class="hero-visual-stars">✧ &nbsp; ✦ &nbsp; ✳</span></div><div class="article-body">{paragraph}</div>{adslot()}{brand_strip() if item['category'] in ('집·이사 꿈','이사정보','청소·관리') else ''}<div class="post-end"><a href="/{kind}/">← {label} 전체보기</a><button type="button" class="share-button" data-copy-link>주소 복사 ⧉</button></div></article><aside class="article-sidebar"><div class="sidebar-panel"><span class="eyebrow">MORE STORIES</span><h3>다른 글도 살펴볼까요?</h3>{side}</div><div class="sidebar-panel sidebar-note"><span>✦</span><p>생활 속 궁금증을<br>천천히 풀어보세요.</p></div></aside></div></div>'''
 return shell(title,item['excerpt'],body,kind if kind=='dreams' else 'life',f'{kind}/{item["slug"]}/','article')

def fortune(kind):
 daily=kind=='today'; title='오늘의 운세' if daily else '주간운세'
 sub=TODAY.strftime('%Y년 %m월 %d일') if daily else f'{WEEK_START.strftime("%Y년 %m월 %d일")} ~ {(WEEK_START+timedelta(days=6)).strftime("%m월 %d일")}'
 title=f'{sub} {title} — 12띠별 운세'
 themes=DAILY_THEMES if daily else WEEKLY_THEMES
 seed=TODAY.toordinal() if daily else WEEK_START.toordinal()
 order=(seed * 7+ (0 if daily else 4))%len(themes)
 buttons=''.join(f'<a href="/fortune/{kind}/{code}/" class="zodiac-chip" data-zodiac="{code}"><span>{emoji}</span>{name}</a>' for code,name,emoji in ANIMALS)
 posts=''
 for i,(code,name,emoji) in enumerate(ANIMALS):
  heading,copy=themes[(order+i*5)%len(themes)]
  extra=(f'{name}의 오늘 키워드는 <strong>{heading}</strong>이에요.' if daily else f'{name}의 이번 주 키워드는 <strong>{heading}</strong>이에요.')
  posts+=f'<a href="/fortune/{kind}/{code}/" class="zodiac-entry" style="display:block"><div class="zodiac-entry-head"><span class="zodiac-emoji">{emoji}</span><div><h2>{name}</h2><span>{esc(heading)}</span></div></div><p>{extra} {esc(copy)}</p><span class="read-link">출생연도별 상세 운세 보기 ↗</span></a>'
 desc=f'{sub}, 12띠별 {"오늘" if daily else "이번 주"} 운세를 가볍게 살펴보세요. 재미로 읽는 꿀팁도사의 운세 메시지.'
 body=f'''<div class="container fortune-page">{breadcrumb((('오늘의 운세' if daily else '주간운세'),None))}<div class="fortune-title"><span class="eyebrow">{ 'DAILY FORTUNE' if daily else 'WEEKLY FORTUNE'}</span><span class="fortune-glyph">✦</span><h1>{'오늘의 운세' if daily else '주간운세'}</h1><p>{esc(sub)}</p><div class="fortune-caption">{ '매일 새로운 메시지로 업데이트됩니다.' if daily else '월요일부터 일요일까지의 한 주를 살펴봅니다.' }<br>오늘의 메시지를 재미로 읽고, 일상의 선택은 스스로 만들어가세요.</div></div><div class="zodiac-pick"><h2>나의 띠를 선택해 보세요</h2><div class="zodiac-grid">{buttons}</div></div><div class="fortune-section-head"><h2>12띠별 운세 보기</h2><p>띠를 누르면 출생연도별 총운·재물운·애정운·건강운·직장운을 확인할 수 있어요.</p></div><div class="zodiac-post-grid">{posts}</div><div class="note-box fortune-disclaimer"><b>🔮 운세 콘텐츠 안내</b><p>본 운세는 재미로 읽는 오락용 창작 메시지입니다. 개인의 미래를 예측하거나 건강·금융·법률 판단에 사용하기 위한 자료가 아닙니다.</p></div><div class="fortune-bottom"><a href="/fortune/{'weekly' if daily else 'today'}/" class="btn btn-primary">{'이번 주 운세' if daily else '오늘의 운세'}도 보기 →</a></div></div>'''
 return shell(title,desc,body,'today' if daily else 'weekly',f'fortune/{kind}/')

def plain(title,content,active=''):
 body=f'<div class="container simple-page">{breadcrumb((title,None))}<div class="page-heading"><span class="eyebrow">KKULTIP DOSA</span><h1>{esc(title)}</h1></div><div class="simple-content">{content}</div></div>'
 return shell(title,DESCRIPTION,body,active,title.lower()+'/')

